10	public record WriteResult(int status, String body) {
11	
12	    private static final ObjectMapper MAPPER = new ObjectMapper();
13	
14	    /** 以给定状态码序列化响应体。 */
15	    public static WriteResult of(int status, Object body) {
16	        try {
