    return ResponseEntity.status(ex.status())
            .body(new ApiDtos.ErrorResponse(ex.code(), ex.getMessage(), ex.violations(),
                    ex.requiredReviewCount(), ex.missingReviewCount(), ex.affectedSegments(),
                    ex.rejectedReviews()));
}

