/** 插入或覆盖某评审人的评审（按段落+语言+评审人唯一）；新评审为 ACTIVE。 */
public void upsertReview(long documentId, ApprovalRow row) {
    int updated = jdbc.update(
            "UPDATE approval SET decision = ?, review_status = ?, conflict_id = ?, source_version = ?, "
                    + "translation_version = ?, reviewed_at = ?, approved_at = CURRENT_TIMESTAMP "
                    + "WHERE document_id = ? AND segment_id = ? AND language = ? AND reviewer = ?",
            row.decision(), row.reviewStatus(), row.conflictId(), row.sourceVersion(),
            row.translationVersion(), Timestamp.from(row.reviewedAt()),
            documentId, row.segmentId(), row.language(), row.reviewer());
    if (updated == 0) {
        jdbc.update("INSERT INTO approval (document_id, segment_id, language, reviewer, decision, "
                        + "review_status, conflict_id, source_version, translation_version, reviewed_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                documentId, row.segmentId(), row.language(), row.reviewer(), row.decision(),
                row.reviewStatus(), row.conflictId(), row.sourceVersion(),
                row.translationVersion(), Timestamp.from(row.reviewedAt()));
    }
}

