/** 查询单个评审人对某段落某语种的最新评审。 */
public Optional<ApprovalRow> findReview(long documentId, String segmentId, String language, String reviewer) {
    List<ApprovalRow> rows = jdbc.query(approvalSelect()
                    + " WHERE document_id = ? AND segment_id = ? AND language = ? AND reviewer = ?",
            APPROVAL_MAPPER, documentId, segmentId, language, reviewer);
    return rows.stream().findFirst();
}

/** 查询文档全部评审（含多评审人、CONFLICTED 与版本失效行），按段落、语种、评审人稳定排序。 */
public List<ApprovalRow> listApprovals(long documentId) {
    return jdbc.query(approvalSelect() + " WHERE document_id = ? "
                    + "ORDER BY segment_id, language, reviewer",
            APPROVAL_MAPPER, documentId);
}

private static String approvalSelect() {
    return "SELECT segment_id, language, reviewer, decision, decision_reason, review_status, "
            + "conflict_id, source_version, translation_version, reviewed_at FROM approval";
}

/** 插入或覆盖某评审人的评审（按段落+语言+评审人唯一）；新评审为 ACTIVE。 */
public void upsertReview(long documentId, ApprovalRow row) {
    int updated = jdbc.update(
            "UPDATE approval SET decision = ?, decision_reason = ?, review_status = ?, conflict_id = ?, "
                    + "source_version = ?, translation_version = ?, reviewed_at = ?, "
                    + "approved_at = CURRENT_TIMESTAMP "
                    + "WHERE document_id = ? AND segment_id = ? AND language = ? AND reviewer = ?",
            row.decision(), row.decisionReason(), row.reviewStatus(), row.conflictId(),
            row.sourceVersion(), row.translationVersion(), Timestamp.from(row.reviewedAt()),
            documentId, row.segmentId(), row.language(), row.reviewer());
    if (updated == 0) {
        jdbc.update("INSERT INTO approval (document_id, segment_id, language, reviewer, decision, "
                        + "decision_reason, review_status, conflict_id, source_version, translation_version, "
                        + "reviewed_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                documentId, row.segmentId(), row.language(), row.reviewer(), row.decision(),
                row.decisionReason(), row.reviewStatus(), row.conflictId(), row.sourceVersion(),
                row.translationVersion(), Timestamp.from(row.reviewedAt()));
    }
}

