        ApiResult blockedReject = reject(docId, "s1", "en", "carol", 1, "译文有误", newRequestId());
        assertThat(blockedReject.status()).isEqualTo(422);
        assertThat(blockedReject.body().get("error").asText()).isEqualTo("REVIEWER_CONFLICT");

