        assertThat(bobReview.get("decision").asText()).isEqualTo("APPROVED");

        // 草稿 2（建文档 1 + 提交译文 1）；冲突登记不增加草稿版本
        ApiResult publishFailed = publish(docId, 2, 0, newRequestId());
        assertThat(publishFailed.status()).isEqualTo(422);
