        return "[{\"language\":\"en\",\"validFrom\":\"" + T0 + "\",\"validTo\":\"" + T1
                + "\",\"reason\":\"" + reason + "\"}]";
    }

    private long readyDoc() throws Exception {
        clock.setFixed(Instant.parse(T0));
        long docId = createDocument(newRequestId(), "[\"en\"]",
                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
